package com.android.tools.lint.checks

import com.android.tools.lint.client.api.UElementHandler
import com.android.tools.lint.detector.api.*
import org.jetbrains.uast.UClass
import org.jetbrains.uast.UMethod

class FragmentDetector : Detector(), SourceCodeScanner {

    override fun applicableUastTypes() = listOf(UClass::class.java)

    override fun createUastHandler(context: JavaContext): UElementHandler {
        return object : UElementHandler() {
            override fun visitClass(node: UClass) {
                if (!isFragmentClass(node, context.evaluator)) return
                // skip androidx.fragment.app.Fragment subclasses
                if (context.evaluator.extendsClass(node, "androidx.fragment.app.Fragment", false)) return

                val constructors = node.constructors
                if (constructors.isEmpty()) {
                    // Java adds default constructor implicitly, Kotlin classes may have default constructor too? UClass.constructors may be empty for no explicit constructor but implicit exists. Actually in UAST for Kotlin default constructor is represented? For Java no explicit constructors means default constructor exists and constructors returns empty? Hmm. Need not flag if no constructors, because implicit empty constructor exists.
                    return
                }

                val hasDefault = constructors.any { it.parameterCount == 0 }

                if (!hasDefault) {
                    context.report(
                        ISSUE,
                        node,
                        context.getNameLocation(node),
                        "Fragment is not instantiatable; it has no empty constructor"
                    )
                }

                for (constructor in constructors) {
                    if (constructor.parameterCount > 0) {
                        val message = "Avoid non-default constructors in fragments: use a default constructor plus `Fragment#setArguments(Bundle)` instead"
                        context.report(
                            ISSUE,
                            constructor,
                            context.getLocation(constructor),
                            message
                        )
                    }
                }
            }
        }
    }

    private fun isFragmentClass(node: UClass, evaluator: JavaEvaluator): Boolean {
        return evaluator.extendsClass(node, "android.app.Fragment", false)
                || evaluator.extendsClass(node, "android.support.v4.app.Fragment", false)
    }

    companion object {
        @JvmField
        val ISSUE: Issue = Issue.create(
            id = "ValidFragment",
            briefDescription = "Fragment not instantiatable",
            explanation = """
                From the Fragment documentation: Every fragment must have an empty constructor, \
                so it can be instantiated when restoring its activity's state. It is strongly \
                recommended that subclasses do not have other constructors with parameters, since \
                these constructors will not be called when the fragment is re-instantiated; instead, \
                arguments can be supplied by the caller with `setArguments(Bundle)` and later retrieved \
                by the Fragment with `getArguments()`.
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(
                FragmentDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}
```

