    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_FRAGMENT);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Attr attribute = element.getAttributeNodeNS(ANDROID_URI, ATTR_NAME);
        if (attribute == null) {
            return;
        }
        String fqcn = attribute.getValue();
        if (fqcn.isEmpty()) {
