                String.format("%1$s is abstract and cannot be instantiated", fqcn));
            return;
        }
        if (fragmentClass.isMemberClass() && !Modifier.isStatic(modifiers)) {
            context.report(ISSUE, attribute, context.getValueLocation(attribute),
                String.format("%1$s must be static", fqcn));
            return;
        }
        Constructor<?>[] constructors = fragmentClass.getConstructors();
        boolean hasDefault = false;
        for (Constructor<?> constructor : constructors) {
            if (constructor.getParameterTypes().length == 0) {
                hasDefault = true;
                break;
            }
        }
        if (!hasDefault) {
            context.report(ISSUE, attribute, context.getValueLocation(attribute),
                String.format("%1$s has no empty constructor", fqcn));
        }
    }

    private static Class<?> getFragmentClass(@NonNull XmlContext context, @NonNull String fqcn) {
        // ... use context.getMainProject().getClassLoader() etc.
    }

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NonNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NonNull UClass node) {
                if (node.isAbstract()) {
                    return;
                }
                if (!isFragment(node, context.getEvaluator())) {
                    return;
                }
                UMethod[] constructors = node.getConstructors();
                if (constructors.length == 0) {
                    return;
                }
                boolean hasDefault = false;
                for (UMethod constructor : constructors) {
                    if (constructor.getParameterList().getParametersCount() == 0) {
                        hasDefault = true;
                    } else {
                        context.report(ISSUE, constructor, context.getLocation(constructor),
                            "Avoid non-default constructors in fragments: use a default constructor plus Fragment#setArguments(Bundle) instead");
                    }
                }
                if (!hasDefault) {
                    context.report(ISSUE, node, context.getNameLocation(node),
                        String.format("This fragment should provide a default constructor (a public constructor with no arguments) as per the Fragment documentation"));
                }
            }
        };
    }

    private static boolean isFragment(@NonNull UClass node, @NonNull JavaEvaluator evaluator) {
        return INHERITORS.any { evaluator.extendsClass(node, it, false) };
    }
}
